BEGIN;
DO $$
DECLARE admin_user_id bigint; sam_organization_id bigint; property_listing_id bigint;
BEGIN
PERFORM pg_advisory_xact_lock(hashtext('sam-import-20966'));
IF EXISTS (SELECT 1 FROM listing_sources WHERE upper(reference_code)='3A0403' OR source_url ~ '[?&]id=20966(&|$)') OR EXISTS (SELECT 1 FROM listings WHERE public_listing_id='70d9f6d4-e781-4d97-b743-a9c50eb70403' OR slug='sam-direct-sale-warehouse-phanat-nikhom-si-wichai-3a0403' OR description ILIKE '%3A0403%' OR (abs(latitude-13.453929)<0.0001 AND abs(longitude-101.186926)<0.0001 AND abs(land_area_sqm-1012)<1)) THEN RAISE NOTICE 'SAM 3A0403 exists; skipping'; RETURN; END IF;
SELECT id INTO admin_user_id FROM auth_users WHERE lower(email)='mapxprop@gmail.com' AND deleted_at IS NULL ORDER BY id LIMIT 1;
SELECT id INTO sam_organization_id FROM organizations WHERE slug='sukhumvit-asset-management-sam' AND verification_status='verified' AND is_active=true AND deleted_at IS NULL ORDER BY id LIMIT 1;
IF admin_user_id IS NULL OR sam_organization_id IS NULL THEN RAISE EXCEPTION 'Existing admin and verified SAM organization required'; END IF;
INSERT INTO public.listings (public_listing_id, user_id, organization_id, created_by_user_id, published_by_user_id, property_type_code, usage_type, listing_type, listing_scope, title, description, sale_price, price_negotiable, land_area_sqm, total_floors, contact_name, contact_phone, contact_email, line_id, show_phone, show_email, address_line1, address_line2, road, latitude, longitude, province_name, district_name, subdistrict_name, listing_status, moderation_status, approved_at, published_at, moderation_submitted_at, moderated_at, is_verified, is_active, source_channel, price_unit, slug) VALUES ('70d9f6d4-e781-4d97-b743-a9c50eb70403', admin_user_id, sam_organization_id, admin_user_id, admin_user_id, 'warehouse', 'business', 'sale', 'whole_property', 'ขายตรง SAM โกดัง พนัสนิคม ถนนศรีวิชัย ที่ดิน 9 แปลงรวม 253 ตร.ว.', 'โกดังเก็บของในตำบลพนัสนิคม อำเภอพนัสนิคม จังหวัดชลบุรี ที่ตั้งต้นทางระบุถนนศรีวิชัย ไม่ปรากฏเลขทะเบียนอาคาร ที่ดิน 9 แปลงติดต่อกัน โฉนดเลขที่ 19655 และ 21239–21246 จำนวน 9 ฉบับ เนื้อที่รวม 2 งาน 53 ตร.ว. หรือ 253 ตร.ว. (1,012 ตร.ม.) ราคาประกาศขายจาก SAM 6,940,000 บาท รหัสทรัพย์ 3A0403

ที่ดินรูปคล้ายสี่เหลี่ยมผืนผ้า ติดถนน 2 ด้าน ด้านทิศตะวันตกกว้างประมาณ 20 เมตร ด้านทิศเหนือประมาณ 52 เมตร ด้านทิศตะวันออกติดร่องน้ำสาธารณประโยชน์กว้างประมาณ 17 เมตร และลึกสุดประมาณ 60 เมตร ถนนหน้าทรัพย์ที่ SAM ระบุคือถนนศรีวิชัย เป็นทางสาธารณประโยชน์ ผิวคอนกรีตกว้างประมาณ 6 เมตร เขตทางประมาณ 12 เมตร ต้องตรวจแนวเขตด้านร่องน้ำและความเหมาะสมของทางเข้าสำหรับรถที่ต้องการใช้งาน

ข้อมูลอาคารที่ต้องตรวจสอบ: รายการรับโอนกรรมสิทธิ์ของ SAM ระบุโกดังชั้นเดียว ไม่ปรากฏเลขทะเบียน ขณะที่ผลสำรวจระบุว่าเป็นโกดังเก็บของสูง 2 ชั้น จึงใช้จำนวนชั้นตามรายการรับโอนและระบุคำบรรยายสำรวจแยกไว้ ไม่ถือว่ามีพื้นที่ใช้สอยสองชั้นที่ยืนยันแล้ว ผู้ซื้อควรตรวจแบบอาคาร ทะเบียน ใบอนุญาต ความสูงจริง และพื้นที่ใช้สอยกับ SAM

ข้อกำหนดการใช้อาคารตามข้อมูล SAM: ทรัพย์อยู่ในบริเวณที่ 2 ตามเทศบัญญัติเทศบาลเมืองพนัสนิคม เรื่องกำหนดบริเวณห้ามก่อสร้าง ดัดแปลง หรือเปลี่ยนการใช้อาคารบางชนิดหรือบางประเภท พ.ศ.2555 ต้นทางระบุผังเมืองสีส้มและย่านที่อยู่อาศัย ผู้ซื้อควรตรวจข้อกำหนดฉบับปัจจุบันและกิจการที่อนุญาตกับเทศบาลก่อนเสนอซื้อ การจัดเป็นหมวดโกดังไม่ใช่การยืนยันว่าใช้เป็นโรงงานหรือประกอบกิจการใดได้ทันที

สถานที่ใกล้เคียงตาม SAM ได้แก่ โรงเรียนเทศบาล 1 วัดพลับ ที่ว่าการอำเภอพนัสนิคม และสถานีตำรวจภูธรอำเภอพนัสนิคม

การเดินทางตาม SAM: ถนนหนองซาก–พนัสนิคม (ทล.315) จากฉะเชิงเทรามุ่งหน้าบ้านบึง ผ่านโรงพยาบาลพนัสนิคม ถึงสี่แยกพนัสนิคม เลี้ยวซ้ายเข้าถนนเมืองเก่าประมาณ 1.2 กิโลเมตร เลี้ยวซ้ายถนนศรีวิชัยประมาณ 200 เมตร แล้วเลี้ยวขวาถนนพาณิชพัฒนา 1 ประมาณ 150 เมตร ทรัพย์อยู่ด้านขวามือ ควรใช้แผนที่ประกอบเพราะต้นทางระบุชื่อถนนในที่ตั้งและขั้นตอนเดินทางต่างกัน

หน้า SAM แสดงสถานะซื้อตรงและราคาข้างต้น ณ วันที่ 11 กันยายน 2569 ติดต่อ SAM โทร 02-686-1888 อีเมล sales@sam.or.th หรือ LINE @samline แจ้งรหัส 3A0403 เพื่อยืนยันสถานะพร้อมขาย ราคา การนัดชม รายการอาคารและข้อกำหนดการใช้ประโยชน์ SAM กล่าวถึงทรัพย์ใกล้เคียงรหัส 3A0404 และ 3A0405 ซึ่งไม่ได้รวมในประกาศนี้

พิกัด 13.453929, 101.186926 ดึงจากลิงก์ระบบนำทาง SAM และตรงกับ Google Map ภาพอาคารและภายในแสดงวันที่ 2 ตุลาคม 2567 คัดภาพไม่ซ้ำ 8 ภาพ รวมผังแปลง ผังอาคารและแผนที่ ต้นทางไม่ระบุพื้นที่ใช้สอย ความสูงเป็นเมตร น้ำหนักบรรทุกพื้น ระบบไฟฟ้า ใบอนุญาตกิจการ ขนาดรถที่รองรับ อายุอาคาร หรือสถานะผู้ครอบครอง จึงต้องยืนยันก่อนซื้อ', 6940000, false, 1012, 1, 'ฝ่ายขายและส่งเสริมกิจกรรมการขาย — SAM', '026861888', 'sales@sam.or.th', '@samline', true, true, 'โกดัง ไม่ปรากฏเลขทะเบียน ถนนศรีวิชัย', 'เข้าทางถนนพาณิชพัฒนา 1 ตามแผนที่ SAM', 'ถนนศรีวิชัย', 13.453929, 101.186926, 'ชลบุรี', 'พนัสนิคม', 'พนัสนิคม', 'active', 'approved', now(), now(), now(), now(), true, true, 'editorial_import', 'total', 'sam-direct-sale-warehouse-phanat-nikhom-si-wichai-3a0403') RETURNING id INTO property_listing_id;
