INSERT INTO public.listing_sources (listing_id, source_type, publisher_name, source_url, reference_code, captured_at, notes) VALUES (property_listing_id, 'editorial_import', 'บริษัท บริหารสินทรัพย์สุขุมวิท จำกัด (SAM)', 'https://www.sam.or.th/site/npa/detail.php?id=20966&keyref=6007684', '3A0403', now(), 'Official source captured 2026-09-11. THB 6,940,000; nine plots totaling 253 sq.wah. Registered single-storey warehouse versus survey two-storey-height wording disclosed; no confirmed second usable floor. SAM-reported municipal Area 2 restrictions under 2012 ordinance and eastern public drainage channel disclosed. Nearby 3A0404/3A0405 excluded. Eight unique images from nine URLs, exact duplicate cover excluded; building photos 2024-10-02. Navigation/map agree. All-status duplicate search found no matches.') ;
INSERT INTO public.listing_translations (listing_id, language_code, title, description, address_line1, address_line2, road, subdistrict_name, district_name, province_name, seo_title, seo_description, translation_status, translation_source, reviewed_at, search_text) VALUES (property_listing_id, 'en', 'SAM Direct Sale: Phanat Nikhom Warehouse, 253 Sq.Wah, THB 6.94M', 'Storage warehouse in Phanat Nikhom subdistrict and district, Chon Buri, with the source address on Si Wichai Road and no stated building registration number. Nine adjoining plots, Chanote 19655 and 21239–21246, total 253 sq.wah (1,012 sq.m.). SAM announced price THB 6,940,000; asset 3A0403.

Approximately rectangular land with two road frontages. The source gives approximately 20 metres on the west, 52 metres on the north, 17 metres along the public drainage channel on the east, and a maximum depth of 60 metres. SAM describes Si Wichai Road as public, with a six-metre concrete carriageway and 12-metre right of way. Verify drainage-channel boundaries and access for the required vehicles.

Registered acquisition describes a single-storey warehouse without a stated registration number. The survey calls it a warehouse two storeys high. The listing uses the registered floor count and separately records the survey wording; two usable floors are not confirmed. Verify building plans, registration, permits, actual height and usable area.

SAM reports the property lies in Area 2 under the Phanat Nikhom municipal ordinance of 2012 restricting construction, alteration or change of use of certain buildings. It reports orange planning zoning and residential surroundings. Confirm current restrictions and permitted activities directly with the municipality. Warehouse categorisation does not confirm factory or business operating permission.

Source-listed nearby places are Municipal School 1, Wat Phlap, Phanat Nikhom district office and police station.

From Chachoengsao toward Ban Bueng on Highway 315, pass Phanat Nikhom Hospital, turn left at Phanat Nikhom intersection onto Mueang Kao Road for 1.2 kilometres, left onto Si Wichai Road for 200 metres, then right onto Phanit Phatthana 1 for 150 metres; the property is on the right. Check the map because the source address and final approach name different roads.

SAM showed direct-purchase status and this price on 11 September 2026. Contact 02-686-1888, sales@sam.or.th or LINE @samline, quoting 3A0403, to confirm availability, price, viewing, buildings and permitted use. Nearby SAM assets 3A0404 and 3A0405 are mentioned by the source but are not included.

Navigation and map agree on 13.453929, 101.186926. Building/interior photos display 2 October 2024. Eight unique images include plot plans, building plan and map. Usable floor area, height in metres, floor loading, electrical capacity, operating licences, supported truck size, age and occupancy are not published; verify before purchase.', 'Warehouse without stated registration number, Si Wichai Road', 'Approach via Phanit Phatthana 1 according to SAM map', 'Si Wichai Road', 'Phanat Nikhom', 'Phanat Nikhom', 'Chon Buri', 'SAM Phanat Nikhom Warehouse — THB 6.94M', 'SAM 3A0403: Phanat Nikhom warehouse on nine plots, 253 sq.wah. THB 6,940,000; municipal use restrictions and building survey difference disclosed.', 'published', 'ai_assisted', now(), 'sam direct sale: phanat nikhom warehouse, 253 sq.wah, thb 6.94m storage warehouse in phanat nikhom subdistrict and district, chon buri, with the source address on si wichai road and no stated building registration number. nine adjoining plots, chanote 19655 and 21239–21246, total 253 sq.wah (1,012 sq.m.). sam announced price thb 6,940,000; asset 3a0403.

approximately rectangular land with two road frontages. the source gives approximately 20 metres on the west, 52 metres on the north, 17 metres along the public drainage channel on the east, and a maximum depth of 60 metres. sam describes si wichai road as public, with a six-metre concrete carriageway and 12-metre right of way. verify drainage-channel boundaries and access for the required vehicles.

registered acquisition describes a single-storey warehouse without a stated registration number. the survey calls it a warehouse two storeys high. the listing uses the registered floor count and separately records the survey wording; two usable floors are not confirmed. verify building plans, registration, permits, actual height and usable area.

sam reports the property lies in area 2 under the phanat nikhom municipal ordinance of 2012 restricting construction, alteration or change of use of certain buildings. it reports orange planning zoning and residential surroundings. confirm current restrictions and permitted activities directly with the municipality. warehouse categorisation does not confirm factory or business operating permission.

source-listed nearby places are municipal school 1, wat phlap, phanat nikhom district office and police station.

